/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_sale_customer_total` AFTER INSERT ON `sales`
 FOR EACH ROW BEGIN
    IF NEW.customer_id IS NOT NULL AND NEW.status = 'completed' THEN
        UPDATE `customers`
        SET `total_purchases` = `total_purchases` + NEW.total
        WHERE `id` = NEW.customer_id;
    END IF;
END */;;
