/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_stock_low_alert` AFTER UPDATE ON `stock`
 FOR EACH ROW BEGIN
    IF NEW.qty <= NEW.min_qty AND (OLD.qty > OLD.min_qty OR OLD.qty IS NULL) THEN
        INSERT IGNORE INTO `stock_alerts`
            (`product_id`, `alert_type`, `threshold`, `created_at`)
        VALUES
            (NEW.product_id,
             IF(NEW.qty = 0, 'out_of_stock', 'low_stock'),
             NEW.min_qty,
             NOW());
    END IF;
END */;;
DELIMITER ;
